// @effect-diagnostics nodeBuiltinImport:off -- this file reads the repository from disk or spawns a process outside a Worker; the Effect FileSystem and ChildProcess services do not exist there.

import { foldkit } from "@foldkit/vite-plugin";
import { legalPages, legalUrl } from "@surveybeat/domain";
import tailwindcss from "@tailwindcss/vite";
import { copyFileSync, mkdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { defineConfig } from "vite";
import type { Plugin } from "vite";
import { answerCatalog } from "./src/messages/answer.ts";
import { answerMessages } from "./src/answer/answer-messages.ts";

const prerenderAnswer = (): Plugin => {
  let outDir = "dist";

  return {
    name: "prerender-answer",
    configResolved(config) {
      outDir = path.resolve(config.root, config.build.outDir);
    },
    transformIndexHtml(html, ctx) {
      if (!ctx.path.endsWith("answer.html") && !html.includes("<!--PRERENDER_STYLE-->")) {
        return html;
      }

      const rawCss = readFileSync(path.resolve(import.meta.dirname, "src/answer/style.css"), "utf8");

      const minCss = rawCss
        .replaceAll(/\/\*[\s\S]*?\*\//g, "")
        .replaceAll(/\s*([{};:,])\s*/g, "$1")
        .replaceAll(/\n\s*/g, "");

      const bootstrapSource = `<script>
(function() {
  try {
    var hash = location.hash;
    var params = new URLSearchParams(hash.slice(1));
    var t = params.get("t");
    var v = params.get("v");
    if (t) {
      sessionStorage.setItem("sb_token", t);
    } else {
      t = sessionStorage.getItem("sb_token") || "";
    }
    window.__sb_token = REDACTED;
    if (v) {
      var n = parseInt(v, 10);
      if (n >= 1 && n <= 5) {
        window.__sb_v = n;
      }
    }
    if (hash) {
      history.replaceState(null, "", location.pathname + location.search);
    }
    if (t && /^[A-Za-z0-9_-]+$/.test(t)) {
      var host = location.hostname;
      var submitOrigin = (host === "dashboard.surveybeat.app" || host === "app.surveybeat.app")
        ? "https://submit.surveybeat.app"
        : (host.endsWith(".dashboard.surveybeat.app")
            ? "https://" + host.replace(".dashboard.surveybeat.app", ".submit.surveybeat.app")
            : (host.endsWith(".app.surveybeat.app")
                ? "https://" + host.replace(".app.surveybeat.app", ".submit.surveybeat.app")
                : location.origin));
      window.__sb_submitOrigin = submitOrigin;
      window.__exchangePromise = fetch(submitOrigin + "/exchange", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ token: t })
      }).then(function(r) {
        if (!r.ok) {
          var err = new Error("HTTP " + r.status);
          err.status = r.status;
          throw err;
        }
        return r.json();
      });
    }
  } catch (e) {}
})();
</script>`;

      const bootstrapScript = bootstrapSource.replaceAll(/\s*\n\s*/g, "");

      const message = answerMessages(answerCatalog);

      const scale = [1, 2, 3, 4, 5]
        .map((value) => {
          const id = value === 1 ? ' id="q1low"' : value === 5 ? ' id="q1high"' : "";

          return `<label><input type="radio" name="q1" value="${value}"><span${id}>${value}</span></label>`;
        })
        .join("");

      const legalLinks = legalPages
        .map(
          (page) =>
            `<a href="${legalUrl(page)}" target="_blank" rel="noopener noreferrer">${message(`answer.legal.${page}`)}</a>`,
        )
        .join("");

      const body = `<main>
  <noscript><p class="err" role="alert">${message("answer.noscript")}</p></noscript>
  <p class="mark">${message("answer.mark")}</p>
  <h1 id="pulse"></h1>
  <p class="test-banner" id="test-banner" hidden></p>
  <p class="err" id="err" role="alert" hidden></p>
  <div id="state-message" role="alert" hidden></div>
  <section data-screen="1" id="screen-1">
    <form id="f1">
      <fieldset>
        <legend id="q1text" tabindex="-1">${message("answer.loading")}</legend>
        <div class="scale">${scale}</div>
      </fieldset>
      <p class="anon" id="anon"></p>
      <button type="submit" id="save" disabled>${message("answer.save")}</button>
    </form>
  </section>
  <div id="remaining-screens" hidden></div>
  <section data-screen="thanks" id="screen-thanks" hidden>
    <h2 tabindex="-1">${message("answer.thanks.title")}</h2>
    <p id="thanks-body">${message("answer.thanks.body")}</p>
    <ul class="actions" id="actions"></ul>
  </section>
</main>
<footer><nav aria-label="${message("answer.legal.label")}">${legalLinks}</nav></footer>`;

      return html
        .replace("<title></title>", `<title>${message("answer.title")}</title>`)
        .replace("<!--PRERENDER_STYLE-->", `<style>${minCss}</style>`)
        .replace("<!--HEAD_BOOTSTRAP-->", bootstrapScript)
        .replace("<!--PRERENDER_BODY-->", body.replaceAll(/>\s*\n\s*</g, "><"));
    },
    closeBundle() {
      const answerHtmlPath = path.resolve(outDir, "answer.html");
      const aDir = path.resolve(outDir, "a");
      mkdirSync(aDir, { recursive: true });
      copyFileSync(answerHtmlPath, path.resolve(aDir, "index.html"));
      copyFileSync(answerHtmlPath, path.resolve(outDir, "a.html"));
    },
  };
};

const preloadAnswerChunks = (): Plugin => ({
  name: "preload-answer-chunks",
  transformIndexHtml: {
    order: "post",
    handler(html, ctx) {
      const { bundle, chunk } = ctx;

      if (!ctx.path.endsWith("answer.html") || bundle === undefined || chunk === undefined) {
        return html;
      }

      const seen = new Set<string>();
      const pending = [...chunk.imports];

      while (pending.length > 0) {
        const fileName = pending.pop() ?? "";
        const imported = bundle[fileName];

        if (seen.has(fileName) || imported === undefined || imported.type !== "chunk") {
          continue;
        }

        seen.add(fileName);
        pending.push(...imported.imports);
      }

      const links = [...seen].map((fileName) => `<link rel="modulepreload" crossorigin href="/${fileName}">`);

      return html.replace("</head>", `${links.join("")}</head>`);
    },
  },
});

export default defineConfig({
  plugins: [tailwindcss(), foldkit(), prerenderAnswer(), preloadAnswerChunks()],
  build: {
    modulePreload: false,
    rolldownOptions: {
      input: {
        app: "index.html",
        answer: "answer.html",
      },
    },
  },
});
// @effect-diagnostics nodeBuiltinImport:off -- this file reads the repository from disk or spawns a process outside a Worker; the Effect FileSystem and ChildProcess services do not exist there.

import { readFileSync } from "node:fs";
import { assert, describe, it } from "@effect/vitest";

/**
 * The design tokens live once in the app's Tailwind theme (`app/app.css`). The answer page cannot
 * load that stylesheet (ADR 0008 budget) and emails cannot use CSS variables, so both repeat the
 * values. These tests fail when a copy drifts from the theme.
 */
const read = (path: string) => readFileSync(new URL(path, import.meta.url), "utf8");

const declarations = (css: string, prefix: string): Map<string, string> =>
  new Map(
    Array.from(css.matchAll(new RegExp(`--${prefix}([a-z0-9-]+):\\s*([^;]+);`, "g")), (m) => [
      m[1] ?? "",
      (m[2] ?? "").trim().toLowerCase(),
    ]),
  );

const darkBlock = (css: string): string => {
  const start = css.indexOf("@media (prefers-color-scheme: dark)");
  assert.isAbove(start, -1, "dark block present");
  const open = css.indexOf("{", css.indexOf(":root", start));

  return css.slice(open, css.indexOf("}", open));
};

const theme = read("./app/app.css");

const lightTheme = theme.slice(0, theme.indexOf("@media (prefers-color-scheme: dark)"));

const themeColors = declarations(lightTheme, "color-");

const themeRadii = declarations(theme, "radius-");

describe("design tokens", () => {
  it("the answer page uses the theme's values", () => {
    const answer = declarations(read("./answer/style.css").split("}")[0] ?? "", "");
    assert.isAbove(answer.size, 0);

    for (const [name, value] of answer) {
      const expected = name.startsWith("radius-")
        ? themeRadii.get(name.slice("radius-".length))
        : themeColors.get(name);

      assert.strictEqual(value, expected, `--${name} in answer/style.css`);
    }
  });

  it("on-primary exists in both schemes", () => {
    assert.isTrue(themeColors.has("on-primary"));
    assert.isTrue(declarations(darkBlock(theme), "color-").has("on-primary"));
  });

  it("the answer page's dark block matches the app's dark block", () => {
    const answer = declarations(darkBlock(read("./answer/style.css")), "");
    const app = declarations(darkBlock(theme), "color-");
    assert.isAbove(answer.size, 0);

    for (const [name, value] of answer) {
      assert.strictEqual(value, app.get(name), `--${name} dark in answer/style.css`);
    }
  });

  it("emails use the theme's light values", () => {
    const source = read("../../../packages/emails/src/theme.ts");

    const block = source.slice(
      source.indexOf("export const colors"),
      source.indexOf("export const darkColors"),
    );

    const email = new Map(
      Array.from(block.matchAll(/(\w+): "(#[0-9A-Fa-f]{6})"/g), (m) => [
        m[1] ?? "",
        (m[2] ?? "").toLowerCase(),
      ]),
    );

