// @effect-diagnostics asyncFunction:off -- Playwright's API is promise-based and these specs never enter an Effect.

import type { Page } from "@playwright/test";

/**
 * The signed-in screens without a session: every read `/auth/session` and `/api` answer is stubbed
 * from the values below, so a test can open a settings, Teams, or Rounds screen on a stage where
 * the only session is the sign-in cookie. Nothing here changes what
 * the screens do; it only supplies the reads they make.
 *
 * The Team is one the caller leads, so the Rounds screen shows its Lead controls, and the two
 * People are one Member and one Organization admin. The stubbed clock-free dates keep the copy
 * stable: `2026-03-02` reads as a Medium date in whichever locale the app is in.
 */
const ORGANIZATION = { id: "org-1", name: "Acme" };

const TEAM = {
  id: "team-1",
  name: "Platform",
  timeZone: "Europe/Berlin",
  yourRole: "lead" as const,
  memberCount: 5,
  nextRoundDate: "2026-03-02",
};

const PULSE = {
  id: "pulse-1",
  name: "Weekly Pulse",
  cadence: { _tag: "Weekly" as const, day: "monday" as const, time: "09:00" },
  questionCount: 3,
  estimatedSeconds: 60,
  paused: false,
  nextRoundDate: "2026-03-02",
};

const ROUND = {
  id: "round-1",
  pulseId: "pulse-1",
  teamId: "team-1",
  status: "ready" as const,
  plannedOpenDate: "2026-03-02",
  plannedOpenAt: 1772442000000,
  openedAt: 1772442000000,
  plannedCloseAt: 1772528400000,
  closedAt: 1772528400000,
  pulseName: "Weekly Pulse",
  invitations: { invited: 5, joinedAfterOpen: 0 },
};

const SETTINGS = {
  name: "Acme",
  minimumGroupSize: 4,
  aiProcessing: false,
  defaultLocale: "en" as const,
  people: [
    { personId: "person-1", email: "ada@example.com", organizationAdmin: false, linked: true },
    { personId: "person-2", email: "grace@example.com", organizationAdmin: true, linked: true },
    { personId: "person-3", email: "linus@example.com", organizationAdmin: false, linked: false },
  ],
  removedPeople: [],
};

const SESSION = {
  _tag: "SignedIn" as const,
  organization: ORGANIZATION,
  personId: "person-1",
  organizationAdmin: true,
  locale: "en" as const,
  detectedLocale: "en" as const,
  organizationLocale: "en" as const,
};

/** What a path answers: a body for the reads above, or 404 for anything else (and the Round's rate). */
const answerFor = (pathname: string): unknown => {
  if (pathname === "/auth/session") return SESSION;
  if (pathname === "/api/organization") return SETTINGS;
  if (pathname === "/api/organization/failed-emails") return { emails: [] };
  if (pathname === "/api/teams") return [TEAM];
  if (pathname === "/api/teams/team-1")
    return {
      team: TEAM,
      roster: [{ personId: "person-1", email: "ada@example.com", role: "lead", since: 1767225600000 }],
      may: {
        update: true,
        manageLeads: true,
        manageMembers: true,
        managePulses: true,
        viewResults: true,
      },
    };
  if (pathname === "/api/teams/team-1/pulses") return { team: TEAM, pulses: [PULSE] };
  if (pathname === "/api/teams/team-1/pulses/pulse-1/rounds")
    return { pulseId: "pulse-1", paused: false, rounds: [ROUND] };
  if (pathname === "/api/teams/team-1/actions") return { teamId: "team-1", actions: [] };
  return undefined;
};

export const stubSignedIn = async (page: Page): Promise<void> => {
  // One handler for both routes so a new read is one line above, not another `page.route`.
  await page.route("**/auth/session", (route) => {
    void route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(SESSION),
    });
  });
  await page.route("**/api/**", (route) => {
    const body = answerFor(new URL(route.request().url()).pathname);
    void route.fulfill({
      status: body === undefined ? 404 : 200,
      contentType: "application/json",
      body: JSON.stringify(body ?? {}),
    });
  });
};
// @effect-diagnostics nodeBuiltinImport:off -- this file reads the repository from disk or spawns a process outside a Worker; the Effect FileSystem and ChildProcess services do not exist there.

import { defineConfig, devices } from "@playwright/test";
import { resolve } from "node:path";
import { flowAttempts, flowLeadFor } from "./flow-lead.ts";

/**
 * End-to-end tests against a deployed stage (SPEC §7) or the app served by a local stage.
 *
 *   E2E_BASE_URL=https://pr-12.app.surveybeat.app pnpm test:e2e
 *   pnpm test:e2e
 *
 * Without `E2E_BASE_URL`, `alchemy dev` deploys the real `MainWorker` (Durable Object, D1 and the
 * sign-in handlers) to local workerd at `http://localhost:1337`, and the static assets are built
 * from `apps/web` first. The specs then drive the same routes a stage answers, `/auth/session`
 * included, so no stub can hide a missing handler.
 */
const root = resolve(import.meta.dirname, "../../..");
const localStageURL = "http://localhost:1337";
const baseURL = process.env["E2E_BASE_URL"] ?? localStageURL;
const retries = process.env["CI"] === undefined ? 0 : 1;
process.env["E2E_FLOW_RUN"] ??= Array.from(crypto.getRandomValues(new Uint8Array(4)), (byte) =>
  byte.toString(16).padStart(2, "0"),
).join("");
const flowLeads = flowAttempts(retries).map((attempt) =>
  flowLeadFor(process.env["E2E_FLOW_RUN"] ?? "", attempt),
);

export default defineConfig({
  testDir: ".",
  testMatch: "**/*.spec.ts",
  forbidOnly: process.env["CI"] !== undefined,
  // A fresh custom hostname can still be settling after the smoke test.
  retries,
  reporter: process.env["CI"] === undefined ? "list" : [["list"], ["github"]],
  outputDir: "../../../test-results/e2e",
  use: { baseURL, trace: "retain-on-failure" },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    // The audit's phone layouts (C4, #160): the signed-in screens the polish pass changed at a
    // 393 x 851 phone, where a table or a row is most likely to break. The answer page tests its
    // own phone width, and the sign-in form is a desktop concern, so only `polish.spec.ts`
    // runs here.
    { name: "phone", testMatch: /polish\.spec\.ts/, use: { ...devices["Pixel 5"] } },
  ],
  ...(process.env["E2E_BASE_URL"]
    ? {}
    : {
        webServer: {
          command:
            "pnpm --filter @surveybeat/web build && exec node_modules/.bin/alchemy dev -c infra/tests/e2e/stack.ts --stage test_e2e --no-input --log-level info",
          cwd: root,
          // Main answers on 1337 while Alchemy is still updating the Submission Worker and the queue consumers, and those updates reset open connections. Playwright starts on the first of `url` and `wait`, so there is no `url`: the stage is ready once Main is on 1337 and the whole deploy is done.
          wait: { stdout: /\[Main\] ready at http:\/\/localhost:1337\b[\s\S]*Done: \d+ succeeded/ },
          timeout: 180_000,
          reuseExistingServer: false,
          gracefulShutdown: { signal: "SIGTERM", timeout: 15_000 },
          env: {
            ORG_CREATION_ALLOWLIST: ["nobody@example.invalid", ...flowLeads].join(","),
          },
        },
      }),
});
