export const shuffleComments = (comments: readonly CommentResult[]): readonly CommentResult[] => {
  const arr = [...comments];

  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = arr[i];
    const target = arr[j];

    if (temp !== undefined && target !== undefined) {
      arr[i] = target;
      arr[j] = temp;
    }
  }

  return arr;
};

