// Builds the JSON the stub server answers, from the domain's own calculators and schemas.
import { writeFileSync } from "node:fs";
import { Schema } from "effect";
import {
  ActionList,
  buildTeamOverview,
  calculateRoundResult,
  MemberHistory,
  PulseDetail,
  PulseList,
  RoundDetail,
  RoundList,
  RoundResult,
  TeamOverview,
  weeklyTeamHealth,
} from "../../packages/domain/src/index.ts";

const enc = <S extends Schema.Top>(schema: S, value: unknown) =>
  Schema.encodeUnknownSync(schema as never)(value);

const DAY = 86_400_000;
const template = weeklyTeamHealth("en");

const TEAMS = [
  { id: "team-platform", name: "Platform", timeZone: "Europe/Berlin", yourRole: "lead", memberCount: 7, nextRoundDate: "2026-11-23" },
  { id: "team-design", name: "Design systems", timeZone: "Europe/Stockholm", yourRole: "member", memberCount: 5, nextRoundDate: "2026-11-24" },
  { id: "team-data", name: "Data", timeZone: "Europe/Berlin", yourRole: "lead", memberCount: 3, nextRoundDate: null },
];
const team = TEAMS[0]!;
const teamSummary = { id: team.id, name: team.name, timeZone: team.timeZone, yourRole: team.yourRole, memberCount: team.memberCount, nextRoundDate: team.nextRoundDate };

const questions = template.questions.map((q, i) => ({
  questionId: `q-${i + 1}`,
  versionId: `q-${i + 1}-v1`,
  templateKey: q.key,
  text: q.text,
  type: q.type,
  dimension: q.dimension,
  hasAnswers: true,
  estimatedSeconds: 15,
}));

const settings = {
  name: "Weekly team health",
  cadence: { _tag: "Weekly", day: "monday", time: "09:00" },
  answerWindowDays: 2,
  reviewWindowDays: 1,
  reminders: 1,
  anonymityMode: "anonymous",
  distribution: "invitation",
};

const pulseDetail = {
  id: "pulse-weekly",
  team: teamSummary,
  settings,
  questions,
  estimatedSeconds: questions.length * 15,
  warnings: [],
  templateQuestions: template.questions,
};

const pulses = {
  team: teamSummary,
  pulses: [
    { id: "pulse-weekly", name: "Weekly team health", cadence: settings.cadence, questionCount: questions.length, estimatedSeconds: questions.length * 15, paused: false, nextRoundDate: "2026-11-23" },
    { id: "pulse-retro", name: "Release retro", cadence: { _tag: "Weekly", day: "thursday", time: "15:00" }, questionCount: 2, estimatedSeconds: 40, paused: true, nextRoundDate: null },
  ],
};

const dates = ["2026-10-05", "2026-10-12", "2026-10-19", "2026-10-26", "2026-11-02", "2026-11-09", "2026-11-16", "2026-11-23"];
const statuses = ["shared", "shared", "shared", "shared", "shared", "shared", "ready", "scheduled"] as const;
const at = (d: string) => Date.parse(`${d}T08:00:00Z`);

const comments = [
  "Too many meetings on Tuesday, hard to focus.",
  "The incident review helped a lot.",
  "Priorities changed twice this week.",
  "Pairing on the migration felt good.",
];

const qInputs = questions.map((q, i) => ({ id: q.versionId, position: i + 1, text: q.text, type: q.type, dimension: q.dimension }));

const results: unknown[] = [];
const history: unknown[] = [];
dates.forEach((d, r) => {
  if (statuses[r] === "scheduled") return;
  const submissions = Array.from({ length: 6 }, (_, s) => ({
    id: `sub-${r}-${s}`,
    answers: qInputs.map((q, qi) => ({
      questionVersionId: q.id,
      value: q.type._tag === "Rating" ? Math.max(1, Math.min(5, 3 + ((s + qi + r) % 3) - (qi === 0 && r > 4 ? 1 : 0))) : null,
      comment: q.type._tag === "Rating" && q.type.comment && s < 2 ? comments[(r + s + qi) % comments.length]! : null,
    })),
  }));
  const res = calculateRoundResult({
    roundId: `round-${r + 1}` as never,
    pulseId: "pulse-weekly" as never,
    teamId: team.id as never,
    status: statuses[r]!,
    plannedOpenDate: d,
    anonymityMode: "anonymous",
    closedAt: at(d) + 2 * DAY,
    effectiveMinimumGroupSize: 4,
    eligibleMembersCount: 7,
    questions: qInputs as never,
    submissions: submissions as never,
    pastRoundsHistory: history as never,
  });
  history.unshift({
    roundId: res.roundId,
    plannedOpenDate: d,
    closedAt: res.closedAt,
    effectiveMinimumGroupSize: 4,
    submissionsCount: res.submissionsCount,
    questions: res.questions.map((q) => ({ questionVersionId: q.questionVersionId, score: q.score, contributors: q.contributors, meetsMinimumGroupSize: q.meetsMinimumGroupSize })),
    dimensions: res.dimensions.map((x) => ({ dimension: x.dimension, score: x.score, usableQuestionCount: x.usableQuestionCount, contributors: x.contributors ?? null, meetsMinimumGroupSize: x.meetsMinimumGroupSize })),
  });
  results.push({ ...res, pulseName: "Weekly team health" });
});

const rounds = dates.map((d, r) => ({
  id: `round-${r + 1}`,
  pulseId: "pulse-weekly",
  teamId: team.id,
  status: statuses[r],
  plannedOpenDate: d,
  plannedOpenAt: at(d),
  openedAt: statuses[r] === "scheduled" ? null : at(d),
  plannedCloseAt: at(d) + 2 * DAY,
  closedAt: statuses[r] === "scheduled" ? null : at(d) + 2 * DAY,
  pulseName: "Weekly team health",
  invitations: statuses[r] === "scheduled" ? null : { invited: 7, joinedAfterOpen: 0 },
}));

const out: Record<string, unknown> = {};
out["/api/teams"] = TEAMS;
for (const t of TEAMS) {
  out[`/api/teams/${t.id}`] = {
    team: t,
    roster: [
      { personId: "person-1", email: "ada@acme.example", role: t.yourRole === "lead" ? "lead" : "member", since: Date.parse("2026-01-05") },
      { personId: "person-2", email: "grace@acme.example", role: "member", since: Date.parse("2026-01-05") },
      { personId: "person-3", email: "linus@acme.example", role: "member", since: Date.parse("2026-02-10") },
      { personId: "person-4", email: "margaret@acme.example", role: "member", since: Date.parse("2026-03-01") },
      { personId: "person-5", email: "alan@acme.example", role: "member", since: Date.parse("2026-04-14") },
    ],
    may: t.yourRole === "lead"
      ? { update: true, manageLeads: true, manageMembers: true, managePulses: true, viewResults: true }
      : { update: false, manageLeads: false, manageMembers: false, managePulses: false, viewResults: true },
  };
  out[`/api/teams/${t.id}/pulses`] = enc(PulseList, { ...pulses, team: t, pulses: t.id === team.id ? pulses.pulses : [] });
  out[`/api/teams/${t.id}/actions`] = enc(ActionList, { teamId: t.id, actions: [] });
  out[`/api/teams/${t.id}/overview`] = enc(
    TeamOverview,
    t.id === team.id
      ? buildTeamOverview({ teamId: team.id as never, results: results as never, minimumGroupSize: 4, actions: [] })
      : { teamId: t.id, rounds: [], dimensions: [], markers: [] },
  );
}
out[`/api/teams/${team.id}/pulses/pulse-weekly`] = enc(PulseDetail, pulseDetail);
out[`/api/teams/${team.id}/pulses/pulse-retro`] = enc(PulseDetail, { ...pulseDetail, id: "pulse-retro", settings: { ...settings, name: "Release retro" }, questions: questions.slice(0, 2) });
out[`/api/teams/${team.id}/pulses/pulse-weekly/rounds`] = enc(RoundList, { pulseId: "pulse-weekly", paused: false, rounds: [...rounds].reverse() });
out[`/api/teams/${team.id}/pulses/pulse-retro/rounds`] = enc(RoundList, { pulseId: "pulse-retro", paused: true, rounds: [] });
rounds.forEach((r) => {
  out[`/api/teams/${team.id}/rounds/${r.id}`] = enc(RoundDetail, {
    ...r,
    team: teamSummary,
    effectiveMinimumGroupSize: 4,
    answerWindowDays: 2,
    reminders: 1,
    anonymityMode: "anonymous",
    distribution: "invitation",
    questions: questions.map((q) => q.versionId),
    failedInvitations: [],
    createdAt: r.plannedOpenAt - 7 * DAY,
  });
  out[`/api/teams/${team.id}/rounds/${r.id}/note`] = { roundId: r.id, note: null };
});
for (const res of results as Array<{ roundId: string }>) {
  out[`/api/teams/${team.id}/rounds/${res.roundId}/results`] = enc(RoundResult, res);
}
out["/api/me/history"] = enc(MemberHistory, {
  rounds: (results as Array<{ roundId: string; plannedOpenDate: string; questions: Array<{ questionVersionId: string; position: number; text: string; type: unknown; score: number | null }> }>)
    .slice(-4)
    .reverse()
    .map((res) => ({
      roundId: res.roundId,
      teamId: team.id,
      teamName: team.name,
      pulseName: "Weekly team health",
      plannedOpenDate: res.plannedOpenDate,
      teamResult: "shown",
      questions: res.questions.map((q) => ({ questionVersionId: q.questionVersionId, position: q.position, text: q.text, type: q.type, teamScore: q.score })),
    })),
});
out["/auth/session"] = {
  _tag: "SignedIn",
  organization: { id: "org-1", name: "Acme" },
  personId: "person-1",
  organizationAdmin: true,
  locale: "en",
  detectedLocale: "en",
  organizationLocale: "en",
};
out["/api/organization"] = {
  name: "Acme",
  minimumGroupSize: 4,
  aiProcessing: false,
  defaultLocale: "en",
  people: [
    { personId: "person-1", email: "ada@acme.example", organizationAdmin: true, linked: true },
    { personId: "person-2", email: "grace@acme.example", organizationAdmin: false, linked: true },
    { personId: "person-3", email: "linus@acme.example", organizationAdmin: false, linked: false },
  ],
  removedPeople: [],
};
out["/api/organization/failed-emails"] = { emails: [] };

writeFileSync(new URL("./fixtures.json", import.meta.url), JSON.stringify(out, null, 1));
console.log(Object.keys(out).length, "paths");

