// Serves apps/web/dist and answers the app's reads from fixtures.json. Every write is logged to
// writes-<label>.ndjson so the before and after runs can be compared request by request.
import { createServer } from "node:http";
import { appendFileSync, existsSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

const here = path.dirname(new URL(import.meta.url).pathname);
const dist = path.resolve(here, "../../apps/web/dist");
const port = Number(process.env.PORT ?? 4410);
const label = process.env.LABEL ?? "run";
const fixtures = JSON.parse(readFileSync(path.join(here, "fixtures.json"), "utf8"));
const log = path.join(here, `writes-${label}.ndjson`);

const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".woff2": "font/woff2", ".svg": "image/svg+xml", ".png": "image/png", ".json": "application/json" };

const qs = [1, 2, 3, 4];
const context = {
  roundId: "round-8",
  pulseName: "Weekly team health",
  minimumGroupSize: 4,
  questions: (fixtures["/api/teams/team-platform/pulses/pulse-weekly"].questions).map((q, i) => ({ id: q.versionId, position: i + 1, text: q.text, type: q.type })),
  actions: [{ id: "a-1", title: "No meetings on Tuesday mornings" }],
  closeTime: Date.now() + 2 * 86400000,
  state: "open",
  hasAnswered: false,
  aiProcessing: false,
};
void qs;

const json = (res, status, body) => {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
};

createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    const p = url.pathname;
    if (req.method !== "GET" && req.method !== "HEAD") {
      appendFileSync(log, JSON.stringify({ method: req.method, path: p, body: body ? safe(body) : null }) + "\n");
      if (p === "/exchange") return json(res, 200, context);
      if (p === "/first-answer" || p === "/answer") return json(res, 200, {});
      if (p.startsWith("/auth/")) return json(res, 200, {});
      const parent = p.replace(/\/(questions|order|settings|skip|unskip|pause|resume|close|share|cancel|retry-result|test-invitation|leads|members)(\/.*)?$/, "");
      if (fixtures[p] !== undefined) return json(res, 200, fixtures[p]);
      if (fixtures[parent] !== undefined && !["/api/teams/team-platform"].includes(parent)) return json(res, 200, fixtures[parent]);
      if (p.endsWith("/test-invitation")) return json(res, 200, { sendId: "send-1" });
      return res.writeHead(204).end();
    }
    if (fixtures[p] !== undefined) return json(res, 200, fixtures[p]);
    if (p.startsWith("/api/") || p.startsWith("/auth/")) return json(res, 404, { _tag: "NotFound" });
    let file = path.join(dist, p);
    if (!file.startsWith(dist)) return res.writeHead(403).end();
    if (!existsSync(file) || statSync(file).isDirectory()) {
      file = p === "/a" || p.startsWith("/a/") ? path.join(dist, "answer.html") : path.join(dist, "index.html");
    }
    res.writeHead(200, { "content-type": types[path.extname(file)] ?? "application/octet-stream" });
    res.end(readFileSync(file));
  });
}).listen(port, "127.0.0.1", () => console.log(`fixture server on http://127.0.0.1:${port} (${label})`));

function safe(s) {
  try { return JSON.parse(s); } catch { return s; }
}

// Walks every dashboard and survey screen at three widths in light and dark, saves full-page shots
// and writes measurements.json. Usage: node inspect.mjs <baseUrl> <outDir>
import { createRequire } from "node:module";
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const require = createRequire(new URL("../../infra/package.json", import.meta.url));
const { chromium } = require("@playwright/test");
const AxeBuilder = require("@axe-core/playwright").default;

const [base = "http://127.0.0.1:4410", out = ".taste-skill/before"] = process.argv.slice(2);
mkdirSync(path.join(out, "shots"), { recursive: true });

const T = "/teams/team-platform";
export const SCREENS = [
  ["teams", "/"],
  ["team", `${T}`],
  ["pulses", `${T}/pulses`],
  ["pulse", `${T}/pulses/pulse-weekly`],
  ["rounds", `${T}/pulses/pulse-weekly/rounds`],
  ["results", `${T}/rounds/round-6`],
  ["results-ready", `${T}/rounds/round-7`],
  ["history", "/history"],
  ["settings", "/settings"],
  ["answer", "/a#t=abcDEF123"],
];
const WIDTHS = [
  [1440, 900],
  [820, 1180],
  [390, 844],
];

const measure = () => {
  const vw = document.documentElement.clientWidth;
  const all = [...document.querySelectorAll("body *")].filter((e) => {
    const r = e.getBoundingClientRect();
    const s = getComputedStyle(e);
    return r.width > 0 && r.height > 0 && s.visibility !== "hidden" && s.display !== "none";
  });
  const textEls = all.filter((e) => [...e.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim().length > 0));
  const sizes = textEls.map((e) => parseFloat(getComputedStyle(e).fontSize));
  const interactive = all.filter((e) => e.matches("a[href],button,input:not([type=hidden]),select,textarea,summary,[role=button],label:has(input)"));
  const small = interactive.filter((e) => {
    const r = e.getBoundingClientRect();
    const inText = e.matches("a") && e.closest("p,li") && getComputedStyle(e).display === "inline";
    return !inText && (r.height < 44 || r.width < 24);
  });
  const overflow = all.filter((e) => e.getBoundingClientRect().right > vw + 1).length;
  const radii = new Set(all.map((e) => getComputedStyle(e).borderTopLeftRadius).filter((r) => r !== "0px"));
  const fontSizes = new Set(sizes.map((s) => `${s}px`));
  const families = new Set(textEls.map((e) => getComputedStyle(e).fontFamily.split(",")[0].trim()));
  const lineLengths = textEls
    .filter((e) => e.matches("p,li,dd,legend"))
    .map((e) => {
      const s = getComputedStyle(e);
      return e.getBoundingClientRect().width / (parseFloat(s.fontSize) * 0.5);
    });
  const h1 = document.querySelector("h1");
  const firstAction = interactive.find((e) => e.closest("main") && e.matches("button,a.btn,[class*=bg-primary]"));
  return {
    docHeight: document.documentElement.scrollHeight,
    pageOverflowX: document.documentElement.scrollWidth > vw + 1,
    elementsPastViewport: overflow,
    textElements: textEls.length,
    minFontPx: Math.min(...sizes),
    under14px: sizes.filter((s) => s < 14).length,
    distinctFontSizes: fontSizes.size,
    fontFamilies: [...families],
    distinctRadii: radii.size,
    interactive: interactive.length,
    tapTargetsUnder44: small.length,
    maxLineChars: Math.round(Math.max(0, ...lineLengths)),
    h1: h1 ? { text: h1.textContent.trim().slice(0, 60), px: parseFloat(getComputedStyle(h1).fontSize) } : null,
    headings: document.querySelectorAll("h1,h2,h3,h4").length,
    firstActionTopPx: firstAction ? Math.round(firstAction.getBoundingClientRect().top + scrollY) : null,
  };
};

const browser = await chromium.launch();
const results = [];
for (const scheme of ["light", "dark"]) {
  for (const [w, h] of WIDTHS) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, colorScheme: scheme, deviceScaleFactor: 1 });
    const page = await ctx.newPage();
    for (const [name, url] of SCREENS) {
      const errors = [];
      page.on("pageerror", (e) => errors.push(String(e)));
      await page.goto(base + url, { waitUntil: "networkidle" });
      await page.waitForTimeout(400);
      const m = await page.evaluate(measure);
      let axe = null;
      if (w === 1440 || w === 390) {
        const r = await new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa", "wcag21aa"]).analyze();
        axe = { violations: r.violations.length, nodes: r.violations.reduce((n, v) => n + v.nodes.length, 0), ids: r.violations.map((v) => `${v.id}:${v.nodes.length}`) };
      }
      await page.screenshot({ path: path.join(out, "shots", `${name}-${w}-${scheme}.png`), fullPage: true });
      results.push({ screen: name, width: w, scheme, ...m, axe, errors });
      page.removeAllListeners("pageerror");
    }
    await ctx.close();
  }
}
await browser.close();
writeFileSync(path.join(out, "measurements.json"), JSON.stringify(results, null, 1));

const light = results.filter((r) => r.scheme === "light");
const sum = (k, rs = light) => rs.reduce((n, r) => n + (r[k] ?? 0), 0);
const summary = {
  screens: SCREENS.length,
  pageOverflowX: light.filter((r) => r.pageOverflowX).map((r) => `${r.screen}@${r.width}`),
  tapTargetsUnder44_at390: sum("tapTargetsUnder44", light.filter((r) => r.width === 390)),
  textUnder14px_all: sum("under14px"),
  minFontPx: Math.min(...light.map((r) => r.minFontPx)),
  maxDistinctFontSizesOnAScreen: Math.max(...light.map((r) => r.distinctFontSizes)),
  maxDistinctRadiiOnAScreen: Math.max(...light.map((r) => r.distinctRadii)),
  maxLineChars: Math.max(...light.map((r) => r.maxLineChars)),
  avgDocHeight390: Math.round(sum("docHeight", light.filter((r) => r.width === 390)) / SCREENS.length),
  axeViolations: results.filter((r) => r.axe).reduce((n, r) => n + r.axe.violations, 0),
  axeNodes: results.filter((r) => r.axe).reduce((n, r) => n + r.axe.nodes, 0),
  axeIds: [...new Set(results.flatMap((r) => r.axe?.ids.map((i) => i.split(":")[0]) ?? []))],
  pageErrors: results.flatMap((r) => r.errors).length,
};
writeFileSync(path.join(out, "summary.json"), JSON.stringify(summary, null, 1));
console.log(JSON.stringify(summary, null, 1));

