    children.push(
      h.div(
        [h.Class("mt-6")],
        [
          appButton(
            {
              text: message("team.addMember.open"),
              onClick: actions.onToggleAddMember,
              className: secondaryButtonClass,
            },
            h,
          ),
        ],
      ),
    );
  }

  if (detail.may.manageMembers && state.addMemberOpen) {
