// Same steps on any build: every nav link, menu, card, toggle and form. Prints one line per step.
import { createRequire } from "node:module";
const require = createRequire(new URL("../../infra/package.json", import.meta.url));
const { chromium } = require("@playwright/test");

const base = process.argv[2];
const browser = await chromium.launch({ channel: "chrome" });
const results = [];
const T = "/teams/team-platform";

const step = async (name, fn) => {
  try {
    await fn();
    results.push(`PASS ${name}`);
  } catch (e) {
    results.push(`FAIL ${name}: ${String(e.message).split("\n")[0].slice(0, 140)}`);
  }
};

const run = async (width) => {
  const ctx = await browser.newContext({ viewport: { width, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  const go = (u) => page.goto(base + u, { waitUntil: "networkidle" });
  const heading = async (text) => {
    await page.getByRole("heading", { level: 1, name: text }).waitFor({ timeout: 4000 });
  };
  const w = `@${width}`;

  await step(`home loads${w}`, async () => { await go("/"); await heading("What needs my attention"); });
  if (width >= 1024) {
    await step(`nav: My history${w}`, async () => { await page.getByRole("navigation", { name: "Main navigation" }).getByRole("link", { name: "My history" }).click(); await page.waitForURL("**/history"); });
    await step(`nav: Organization settings${w}`, async () => { await page.getByRole("navigation", { name: "Main navigation" }).getByRole("link", { name: "Organization settings" }).click(); await page.waitForURL("**/settings"); });
    await step(`nav: Teams${w}`, async () => { await page.getByRole("navigation", { name: "Main navigation" }).getByRole("link", { name: "Teams" }).click(); await heading("What needs my attention"); });
    await step(`account menu opens${w}`, async () => { await page.getByRole("button", { name: /Account menu/ }).click(); await page.getByRole("button", { name: "Sign out" }).waitFor({ timeout: 3000 }); await page.keyboard.press("Escape"); });
  } else {
    await step(`phone menu opens${w}`, async () => { await page.getByRole("button", { name: "Menu" }).click(); await page.getByRole("link", { name: "My history" }).waitFor({ timeout: 3000 }); });
    await step(`phone menu: My history${w}`, async () => { await page.getByRole("link", { name: "My history" }).click(); await page.waitForURL("**/history"); await go("/"); });
  }
  await step(`attention item -> results${w}`, async () => { await page.getByRole("link", { name: "Weekly team health" }).first().click(); await page.waitForURL("**/rounds/**"); await go("/"); });
  await step(`team card -> team${w}`, async () => { await page.getByRole("link", { name: /^Platform/ }).first().click(); await page.waitForURL(`**${T}`); await heading("Platform"); });
  await step(`create team form sends${w}`, async () => {
    await go("/");
    await page.getByRole("button", { name: "Create Team" }).click();
    await page.getByLabel("Team name").fill("Support");
    await page.getByLabel("Lead's email").fill("lead@acme.example");
    await page.getByRole("button", { name: "Create Team" }).click();
    await page.waitForTimeout(500);
  });

  await go(T);
  await step(`team: View Results${w}`, async () => { await page.getByRole("link", { name: "View Results" }).click(); await page.waitForURL("**/rounds/round-6"); await go(T); });
  await step(`team: recent round link${w}`, async () => { await page.getByRole("link", { name: /Oct 12, 2026/ }).click(); await page.waitForURL("**/rounds/round-2"); await go(T); });
  await step(`team: table view toggle${w}`, async () => { await page.getByRole("button", { name: "Table view" }).first().click(); await page.getByRole("table").first().waitFor({ timeout: 3000 }); await page.getByRole("button", { name: "Chart view" }).first().click(); });
  await step(`team: rename sends${w}`, async () => { await page.getByRole("button", { name: "Rename Team" }).click(); await page.getByLabel("Team name").fill("Platform core"); await page.getByRole("button", { name: /^Rename/ }).last().click(); await page.waitForTimeout(500); });
  await go(T);
  await step(`team: add member sends${w}`, async () => { await page.getByRole("button", { name: "Add member" }).click(); await page.getByRole("textbox").last().fill("new@acme.example"); await page.locator("form").last().getByRole("button").first().click(); await page.waitForTimeout(500); });
  await go(T);
  await step(`team: assign lead sends${w}`, async () => { await page.getByRole("button", { name: "Assign Lead" }).click(); await page.getByRole("textbox").last().fill("grace@acme.example"); await page.locator("form").last().getByRole("button").first().click(); await page.waitForTimeout(500); });
  await go(T);
  await step(`team: row actions menu + remove confirm${w}`, async () => { await page.getByText("Actions ›").nth(1).click(); await page.getByRole("button", { name: "Remove member" }).first().click(); await page.getByRole("alertdialog").getByRole("button", { name: "Remove member" }).click(); await page.waitForTimeout(500); });
  await go(T);
  await step(`team: Pulses${w}`, async () => { await page.getByRole("link", { name: "Pulses" }).first().click(); await page.waitForURL("**/pulses"); });
  await step(`pulses: pulse card${w}`, async () => { await page.getByRole("link", { name: /Weekly team health/ }).first().click(); await page.waitForURL("**/pulse-weekly"); });
  await step(`pulse: move down sends${w}`, async () => { await page.getByRole("button", { name: /Move down/ }).first().click(); await page.waitForTimeout(400); });
  await step(`pulse: write question sends${w}`, async () => { await page.getByRole("button", { name: /Write a question/ }).click(); await page.getByLabel(/Question/).first().fill("How was the release week?"); await page.locator("form").filter({ hasText: "How was" }).getByRole("button", { name: /Add/ }).last().click(); await page.waitForTimeout(400); });
  await go(`${T}/pulses/pulse-weekly`);
  await step(`pulse: send test sends${w}`, async () => { await page.getByRole("button", { name: /test/i }).first().click(); await page.waitForTimeout(400); });
  await step(`pulse: settings save sends${w}`, async () => { await page.getByRole("button", { name: /Save settings/ }).click(); await page.waitForTimeout(400); });
  await step(`pulse: Rounds tab${w}`, async () => { await page.getByRole("link", { name: "Rounds" }).first().click(); await page.waitForURL("**/rounds"); });
  await step(`rounds: view results${w}`, async () => { await page.getByRole("link", { name: /View Results/ }).first().click(); await page.waitForURL("**/rounds/round-*"); });

  await go(`${T}/rounds/round-7`);
  await step(`results: share sends${w}`, async () => { await page.getByRole("button", { name: /Share/ }).first().click(); await page.waitForTimeout(400); });
  await go(`${T}/rounds/round-6`);
  await step(`results: breadcrumb${w}`, async () => { await page.getByRole("navigation", { name: /Breadcrumb/i }).getByRole("link").first().click(); await page.waitForURL(`**${T}`); await go(`${T}/rounds/round-6`); });
